import { useState, useEffect, useRef, useMemo } from "react";
// --- Supabase client (loaded from CDN via index.html) ------------------------
const SUPABASE_URL  = import.meta.env.VITE_SUPABASE_URL  || "";
const SUPABASE_KEY  = import.meta.env.VITE_SUPABASE_ANON_KEY || "";
let supabase = null;
try {
  if (SUPABASE_URL && SUPABASE_KEY && typeof window !== "undefined" && window.supabase) {
    supabase = window.supabase.createClient(SUPABASE_URL, SUPABASE_KEY);
  }
} catch(e) { supabase = null; }

// --- DB helpers ---------------------------------------------------------------
// All DB calls are wrapped so the app works even without a DB connection

const db = {
  // -- Auth --------------------------------------------------------------------
  async signUp(email, password) {
    if (!supabase) return { user: null, error: null };
    const { data, error } = await supabase.auth.signUp({ email, password });
    return { user: data?.user, error };
  },

  async signIn(email, password) {
    if (!supabase) return { user: null, error: null };
    const { data, error } = await supabase.auth.signInWithPassword({ email, password });
    return { user: data?.user, error };
  },

  async signOut() {
    if (!supabase) return;
    await supabase.auth.signOut();
  },

  async getSession() {
    if (!supabase) return null;
    const { data } = await supabase.auth.getSession();
    return data?.session?.user || null;
  },

  // -- Business -----------------------------------------------------------------
  async createBusiness(userId, profile) {
    if (!supabase) return { data: null, error: null };
    const slug = profile.name.toLowerCase().replace(/[^a-z0-9]/g,"-").replace(/-+/g,"-");
    const { data, error } = await supabase.from("businesses").insert({
      owner_id:     userId,
      name:         profile.name,
      slug:         profile.slug || slug,
      phone:        profile.phone || null,
      website:      profile.website || null,
      service_area: profile.serviceArea || null,
      logo_url:     null,  // logo uploads handled separately
      categories:   profile.categories || [],
    }).select().single();
    return { data, error };
  },

  async getBusiness(userId) {
    if (!supabase) return null;
    const { data } = await supabase
      .from("businesses")
      .select("*")
      .eq("owner_id", userId)
      .single();
    return data;
  },

  async updateBusiness(businessId, updates) {
    if (!supabase) return;
    await supabase.from("businesses").update(updates).eq("id", businessId);
  },

  // -- Business settings --------------------------------------------------------
  async createSettings(businessId) {
    if (!supabase) return;
    await supabase.from("business_settings").insert({ business_id: businessId });
  },

  async getSettings(businessId) {
    if (!supabase) return null;
    const { data } = await supabase
      .from("business_settings")
      .select("*")
      .eq("business_id", businessId)
      .single();
    return data;
  },

  async updateSettings(businessId, updates) {
    if (!supabase) return;
    await supabase.from("business_settings")
      .upsert({ business_id: businessId, ...updates });
  },

  // -- Reviews -------------------------------------------------------------------
  async submitReview(businessId, reviewData) {
    if (!supabase) return { data: null, error: null };
    const { data, error } = await supabase.from("reviews").insert({
      business_id:    businessId,
      customer_name:  reviewData.name,
      customer_email: reviewData.email,
      rating:         reviewData.rating,
      review_text:    reviewData.usePolished && reviewData.polishedText
                        ? reviewData.polishedText : reviewData.text,
      is_private:     reviewData.rating <= 3,
      phone:          reviewData.phone || null,
      best_time:      reviewData.bestTime || null,
      private_note:   reviewData.privateNote || null,
    }).select().single();
    return { data, error };
  },

  async getReviews(businessId) {
    if (!supabase) return [];
    const { data } = await supabase
      .from("reviews")
      .select("*")
      .eq("business_id", businessId)
      .order("created_at", { ascending: false })
      .limit(50);
    return data || [];
  },

  // -- Demo leads ----------------------------------------------------------------
  async saveDemoLead(name, email, step = 1) {
    if (!supabase) return;
    await supabase.from("demo_leads").upsert({
      name, email, step,
      updated_at: new Date().toISOString(),
    }, { onConflict: "email" });
  },

  async logDemoEvent(email, event) {
    if (!supabase) return;
    await supabase.from("demo_leads").upsert({
      email, event,
      updated_at: new Date().toISOString(),
    }, { onConflict: "email" });
  },

  async getDemoLeads() {
    if (!supabase) return [];
    const { data } = await supabase
      .from("demo_leads")
      .select("*")
      .order("updated_at", { ascending: false });
    return data || [];
  },
};

