const buildBusinessPlatforms = () =>
  PLATFORM_CATALOG
    .filter(c => c.active)
    .map((c, idx) => ({
      id:                  `bp_${c.id}`,          // business_platform row id
      business_id:         "unity1",
      platform_catalog_id: c.id,
      custom_review_url:   "",
      enabled:             true,  // all platforms on by default — business can disable in settings
      sort_order:          c.pri,
    }));

function joinPlatforms(catalog, bizPlatforms) {
  return bizPlatforms
    .map(bp => {
      const cat = catalog.find(c => c.id === bp.platform_catalog_id) || {};
      return {
        ...cat,
        ...bp,
        effective_url: bp.custom_review_url || cat.default_url_pattern || "",
      };
    })
    .sort((a, b) => (a.sort_order ?? 999) - (b.sort_order ?? 999));
}

