// --- Atoms --------------------------------------------------------------------
function StarRating({ value, onChange, readonly=false }) {
  const [hov, setHov] = useState(0);
  return (
    <div className="flex gap-2">
      {[1,2,3,4,5].map(s => (
        <button key={s} disabled={readonly}
          className={`text-5xl transition-all duration-100 ${!readonly?"cursor-pointer":"cursor-default"} ${s<=(hov||value)?"opacity-100 scale-110":"opacity-25"}`}
          onMouseEnter={()=>!readonly&&setHov(s)} onMouseLeave={()=>!readonly&&setHov(0)}
          onClick={()=>!readonly&&onChange?.(s)}>⭐</button>
      ))}
    </div>
  );
}

function ProgressBar({ current, total }) {
  const pct = total>0 ? Math.round((current/total)*100) : 0;
  return (
    <div className="w-full rounded-full h-2.5" style={{ background:"rgba(255,255,255,0.1)" }}>
      <div className="h-2.5 rounded-full transition-all duration-700"
        style={{ width:`${pct}%`, background:"linear-gradient(90deg,#6D28D9,#A855F7,#C084FC)" }}/>
    </div>
  );
}

function Toggle({ value, onChange, size="md" }) {
  return (
    <button onClick={()=>onChange(!value)}
      className="relative w-12 h-6 rounded-full transition-all duration-300 flex-shrink-0"
      style={{ background:value?"linear-gradient(135deg,#7C3AED,#A855F7)":"rgba(255,255,255,0.15)" }}>
      <div className={`absolute top-1 w-4 h-4 rounded-full bg-white shadow transition-all duration-300 ${value?"left-7":"left-1"}`}/>
    </button>
  );
}

function Card({ children, className="", accent, colorBorder, warn, green }) {
  let bg="rgba(255,255,255,0.05)", bdr="1px solid rgba(255,255,255,0.1)";
  if(accent)       { bg="rgba(124,58,237,0.1)";  bdr="1px solid rgba(168,85,247,0.35)"; }
  if(warn)         { bg="rgba(245,158,11,0.07)";  bdr="1px solid rgba(245,158,11,0.25)"; }
  if(green)        { bg="rgba(34,197,94,0.08)";   bdr="1px solid rgba(34,197,94,0.25)"; }
  if(colorBorder)  { bdr=`1px solid ${colorBorder}44`; }
  return <div className={`rounded-2xl ${className}`} style={{ background:bg, border:bdr }}>{children}</div>;
}

function Spinner() {
  return <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin mx-auto"/>;
}

function PlatformDot({ platform, status, active }) {
  const bg  = active?`${platform.color}33`:status==="posted"?"rgba(34,197,94,0.15)":"rgba(255,255,255,0.06)";
  const bdr = active?`1px solid ${platform.color}77`:status==="posted"?"1px solid rgba(34,197,94,0.35)":"1px solid rgba(255,255,255,0.1)";
  const clr = active?platform.color:status==="posted"?"#86efac":"#6b7280";
  const pre = active?"▶ ":status==="posted"?"✓ ":status==="skipped"?"↷ ":"";
  return (
    <div className="flex-shrink-0 px-3 py-1 rounded-full text-xs font-semibold"
      style={{ background:bg, border:bdr, color:clr }}>{pre}{platform.name}</div>
  );
}

function InputField({ label, type="text", value, onChange, placeholder, note }) {
  const [focused,setFocused] = useState(false);
  return (
    <div className="mb-4">
      <label className="block text-gray-100 text-xs mb-1.5 font-semibold uppercase tracking-wide">
        {label}{note&&<span className="text-gray-400 normal-case font-normal ml-1">{note}</span>}
      </label>
      <input type={type} value={value} onChange={e=>onChange(e.target.value)} placeholder={placeholder}
        className="w-full px-4 py-3 rounded-xl text-white text-sm placeholder-gray-400"
        style={{ background:"rgba(255,255,255,0.14)", border:focused?"1px solid rgba(168,85,247,0.9)":"1px solid rgba(255,255,255,0.28)", outline:"none", transition:"border 0.2s" }}
        onFocus={()=>setFocused(true)} onBlur={()=>setFocused(false)}/>
    </div>
  );
}

function PhotoUpload({ photo, onPhoto }) {
  const ref = useRef(null);
  const [preview, setPreview] = useState(null);
  const handleFile = (file) => {
    if(!file || !file.type.startsWith("image/")) return;
    const reader = new FileReader();
    reader.onload = (e) => { setPreview(e.target.result); onPhoto(file); };
    reader.readAsDataURL(file);
  };
  const remove = () => { setPreview(null); onPhoto(null); if(ref.current) ref.current.value=""; };
  return (
    <div className="mb-5">
      <input ref={ref} type="file" accept="image/*" className="hidden"
        onChange={e=>handleFile(e.target.files?.[0])}/>
      {!preview ? (
        <button type="button" onClick={()=>ref.current?.click()}
          onDrop={e=>{ e.preventDefault(); handleFile(e.dataTransfer.files?.[0]); }}
          onDragOver={e=>e.preventDefault()}
          className="w-full py-4 rounded-xl text-gray-400 text-sm flex flex-col items-center gap-1.5 hover:bg-white/5 transition-colors"
          style={{ border:"1px dashed rgba(255,255,255,0.2)" }}>
          <span className="text-2xl">📷</span>
          <span>Add a photo <span className="text-gray-400">(optional)</span></span>
          <span className="text-xs text-gray-400">Tap to choose or drag &amp; drop</span>
        </button>
      ) : (
        <div className="relative rounded-xl overflow-hidden" style={{ border:"1px solid rgba(168,85,247,0.5)" }}>
          <img src={preview} alt="Preview" className="w-full max-h-48 object-cover"/>
          <button onClick={remove} className="absolute top-2 right-2 w-7 h-7 rounded-full flex items-center justify-center text-white text-xs font-bold"
            style={{ background:"rgba(0,0,0,0.65)" }}>✕</button>
          <div className="absolute bottom-2 left-2 text-xs px-2 py-1 rounded-lg text-green-300 font-semibold"
            style={{ background:"rgba(0,0,0,0.65)" }}>✓ Photo added</div>
        </div>
      )}
    </div>
  );
}

// Token burst celebration overlay
function TokenBurst({ amount, onDone }) {
  useEffect(() => {
    const t = setTimeout(onDone, 2400);
    return () => clearTimeout(t);
  }, []);
  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center"
      style={{ background:"rgba(0,0,0,0.75)", backdropFilter:"blur(4px)" }}>
      <div className="text-center px-8 py-10 rounded-3xl"
        style={{ background:"linear-gradient(145deg,rgba(109,40,217,0.4),rgba(124,58,237,0.3))", border:"1px solid rgba(168,85,247,0.5)" }}>
        <div className="text-7xl mb-4" style={{ animation:"bounce 0.6s infinite" }}>🎉</div>
        <div className="text-5xl font-black text-white mb-2" style={{ fontFamily:"'Syne',sans-serif" }}>
          +{amount} tokens!
        </div>
        <div className="text-purple-300 text-lg">Nice! Keep going ✨</div>
        <div className="mt-6 flex gap-2 justify-center">
          {[...Array(amount>10?10:amount)].map((_,i)=>(
            <span key={i} className="text-2xl" style={{ animationDelay:`${i*0.1}s` }}>⭐</span>
          ))}
        </div>
      </div>
    </div>
  );
}

