// --- Demo Token System --------------------------------------------------------
// Generates and validates 30-day demo access tokens
// Token format: base64(JSON{name, email, created, expires})
const DEMO_PRICE    = 25;
const DEMO_DAYS     = 30;
const WARN_AT_DAYS  = [25, 28];  // show banner at these days remaining

const generateDemoToken = (name, email) => {
  const now     = Date.now();
  const payload = { name, email, created: now, expires: now + DEMO_DAYS * 86400000 };
  return btoa(JSON.stringify(payload));
};

const parseDemoToken = (token) => {
  try {
    const payload = JSON.parse(atob(token));
    if (!payload.expires) return null;
    const now        = Date.now();
    const daysLeft   = Math.ceil((payload.expires - now) / 86400000);
    const daysUsed   = Math.floor((now - payload.created) / 86400000);
    const expired    = now > payload.expires;
    const shouldWarn = !expired && WARN_AT_DAYS.some(d => daysLeft <= d);
    return { ...payload, daysLeft, daysUsed, expired, shouldWarn };
  } catch { return null; }
};

const getDemoFromUrl = () => {
  try {
    const params = new URLSearchParams(window.location.search);
    const t = params.get("t") || params.get("demo");
    if (t) return parseDemoToken(t);
  } catch {}
  return null;
};

// Save abandoned email for lead capture
const saveAbandonedLead = (email, name = "", step = 1) => {
  try {
    const existing = JSON.parse(localStorage.getItem("re_abandoned_leads") || "[]");
    const record = { email, name, step, timestamp: Date.now(), url: window.location.href };
    const updated = [...existing.filter(r => r.email !== email), record];
    localStorage.setItem("re_abandoned_leads", JSON.stringify(updated));
  } catch {}
};

// Log demo expiry conversion event
const logDemoEvent = (token, event) => {
  try {
    const events = JSON.parse(localStorage.getItem("re_demo_events") || "[]");
    events.push({ ...token, event, timestamp: Date.now() });
    localStorage.setItem("re_demo_events", JSON.stringify(events));
  } catch {}
};


